// ================================================================
//            PROVIDED TEST HARNESS -- DO NOT EDIT THIS FILE
// ================================================================
//
// usage: ./task3.out [colsum_base] [colsum] [abt_base] [abt]
//        (no argument = colsum_base colsum abt; abt_base alone takes several seconds)
//
// Runs each kernel named, prints its best time and whether the result is
// correct. The result is checked against a fixed hash of the correct output.

#include <algorithm>
#include <chrono>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <vector>
#include "kernels.h"

constexpr int N_COLSUM = 4096;   // Part A: 4096 x 4096 ints, 64 MB
constexpr int N_ABT    = 1024;   // Part B: three 1024 x 1024 ints, 4 MB each
constexpr uint64_t HASH_COLSUM = 0x180e842b885ad5b3ull;   // hash of the correct s
constexpr uint64_t HASH_ABT    = 0x10b52bf8a999f883ull;   // hash of the correct C

static uint64_t fnv(const std::vector<int>& v) {
    uint64_t h = 1469598103934665603ull;
    for (int x : v) { h ^= (uint32_t)x; h *= 1099511628211ull; }
    return h;
}

struct Entry {
    const char* name;
    bool abt;       // Part B kernel
    void (*colsum)(const int*, int, int*);
    void (*f_abt)(const int*, const int*, int, int*);
    int reps;
    double ms;      // best time, < 0 if not run or wrong
};

int main(int argc, char** argv) {
    Entry k[] = {{"colsum_base", false, colsum_base, nullptr, 3, -1},
                 {"colsum", false, colsum_fast, nullptr, 5, -1},
                 {"abt_base", true, nullptr, abt_base, 1, -1},
                 {"abt", true, nullptr, abt_fast, 3, -1}};
    bool want[4] = {argc == 1, argc == 1, false, argc == 1};
    for (int a = 1; a < argc; a++) {
        bool known = false;
        for (int n = 0; n < 4; n++)
            if (std::strcmp(argv[a], k[n].name) == 0) want[n] = known = true;
        if (!known) {
            std::fprintf(stderr, "unknown kernel '%s' (use colsum_base, colsum, abt_base, abt)\n", argv[a]);
            return 1;
        }
    }

    // fixed pseudo-random inputs, the same on every run
    std::vector<int> A((size_t)N_COLSUM * N_COLSUM), s(N_COLSUM);
    std::vector<int> X((size_t)N_ABT * N_ABT), Y((size_t)N_ABT * N_ABT), C((size_t)N_ABT * N_ABT);
    uint32_t r = 12345;
    for (auto& v : A) { r = r * 1664525u + 1013904223u; v = (r >> 8) % 100; }
    for (auto& v : X) { r = r * 1664525u + 1013904223u; v = (r >> 8) % 10; }
    for (auto& v : Y) { r = r * 1664525u + 1013904223u; v = (r >> 8) % 10; }

    int failed = 0;
    for (int n = 0; n < 4; n++) {
        if (!want[n]) continue;
        Entry& e = k[n];
        std::vector<int>& out = e.abt ? C : s;
        double best = 1e30;
        for (int rep = 0; rep < e.reps; rep++) {
            std::fill(out.begin(), out.end(), 0);
            auto t0 = std::chrono::steady_clock::now();
            if (e.abt) e.f_abt(X.data(), Y.data(), N_ABT, C.data());
            else       e.colsum(A.data(), N_COLSUM, s.data());
            best = std::min(best, std::chrono::duration<double, std::milli>(
                                      std::chrono::steady_clock::now() - t0).count());
        }
        uint64_t h = fnv(out);
        bool ok = h == (e.abt ? HASH_ABT : HASH_COLSUM);
        failed |= !ok;
        e.ms = ok ? best : -1;     // a wrong result gets no speedup line
        std::printf("%-12s %10.1f ms  %s\n", e.name, best, ok ? "PASS" : "FAIL (wrong result)");
        if (std::getenv("TASK3_HASH")) std::printf("  hash 0x%016llxull\n", (unsigned long long)h);
    }
    if (k[0].ms > 0 && k[1].ms > 0) std::printf("speedup colsum over colsum_base = %.2fx\n", k[0].ms / k[1].ms);
    if (k[2].ms > 0 && k[3].ms > 0) std::printf("speedup abt over abt_base       = %.2fx\n", k[2].ms / k[3].ms);
    return failed;
}
